import json, re, statistics
rows=[json.loads(l) for l in open('/tmp/probe/hf50.jsonl')]
def norm(x): return str(x).replace(',','').replace('$','').strip().rstrip('.').strip()
def box(s):
    ms=re.findall(r'\\boxed\{([^{}]*)\}', s); return norm(ms[-1]) if ms else None
def hash_(s):
    ms=re.findall(r'####\s*([^\n]*)', s); return norm(ms[-1]) if ms else None
def lastnum(s):
    ms=re.findall(r'-?\d[\d,\.]*', s); return norm(ms[-1]) if ms else None
n=len(rows)
for name,fn in [('hash',hash_),('box',box),('either',None),('lastnum',lastnum)]:
    if fn is None:
        c=sum(1 for r in rows if box(r['output'])==norm(r['gts']) or hash_(r['output'])==norm(r['gts']))
    else:
        c=sum(1 for r in rows if fn(r['output'])==norm(r['gts']))
